INSERT INTO creators (name, slug, bio, category, skills, community, province, image_url, portfolio_images, story_id, featured) VALUES
('Tendai Mahachi', 'tendai-mahachi', 'A stone sculptor from Guruve who has been carving for 15 years. His work explores themes of family, transformation, and the connection between humans and animals.', 'Sculptor', ARRAY['Stone sculpture', 'Springstone carving', 'Serpentite'], 'Shona', 'Mashonaland Central', 'https://images.pexels.com/photos/1145720/pexels-photo-1145720.jpeg?auto=compress&cs=tinysrgb&w=400', ARRAY['https://images.pexels.com/photos/1145720/pexels-photo-1145720.jpeg?auto=compress&cs=tinysrgb&w=400', 'https://images.pexels.com/photos/3270223/pexels-photo-3270223.jpeg?auto=compress&cs=tinysrgb&w=400'], (SELECT id FROM stories WHERE slug='stone-sculpture'), true),
('Rumbi Katsande', 'rumbi-katsande', 'A mbira player and teacher from Harare. She runs workshops for young people, keeping the mbira tradition alive while experimenting with fusion sounds.', 'Musician', ARRAY['Mbira', 'Hosho', 'Vocals', 'Teaching'], 'Shona', 'Harare', 'https://images.pexels.com/photos/167636/pexels-photo-167636.jpeg?auto=compress&cs=tinysrgb&w=400', ARRAY['https://images.pexels.com/photos/167636/pexels-photo-167636.jpeg?auto=compress&cs=tinysrgb&w=400'], (SELECT id FROM stories WHERE slug='mbira-music'), true),
('Nompumelelo Sibanda', 'nompumelelo-sibanda', 'A basket weaver from Bulawayo who creates intricate pieces using traditional Ndebele weaving techniques with contemporary designs.', 'Craftsperson', ARRAY['Basket weaving', 'Grass craft', 'Beadwork'], 'Ndebele', 'Bulawayo', 'https://images.pexels.com/photos/4464036/pexels-photo-4464036.jpeg?auto=compress&cs=tinysrgb&w=400', ARRAY['https://images.pexels.com/photos/4464036/pexels-photo-4464036.jpeg?auto=compress&cs=tinysrgb&w=400'], NULL, false),
('Tafadzwa Chirwa', 'tafadzwa-chirwa', 'A photographer documenting contemporary Zimbabwean life — street scenes, cultural events, and the everyday beauty of Harare.', 'Photographer', ARRAY['Photography', 'Documentary', 'Street photography'], 'Shona', 'Harare', 'https://images.pexels.com/photos/1264210/pexels-photo-1264210.jpeg?auto=compress&cs=tinysrgb&w=400', ARRAY['https://images.pexels.com/photos/1264210/pexels-photo-1264210.jpeg?auto=compress&cs=tinysrgb&w=400', 'https://images.pexels.com/photos/2859169/pexels-photo-2859169.jpeg?auto=compress&cs=tinysrgb&w=400'], (SELECT id FROM stories WHERE slug='youth-culture-harare'), false),
('Sekuru Chigamba', 'sekuru-chigamba', 'An elder and traditional healer from Masvingo who holds deep knowledge of Shona spiritual practices, rainmaking traditions, and medicinal plants.', 'Cultural Practitioner', ARRAY['Traditional healing', 'Rainmaking ceremonies', 'Herbal medicine', 'Storytelling'], 'Shona', 'Masvingo', 'https://images.pexels.com/photos/2387873/pexels-photo-2387873.jpeg?auto=compress&cs=tinysrgb&w=400', ARRAY['https://images.pexels.com/photos/2387873/pexels-photo-2387873.jpeg?auto=compress&cs=tinysrgb&w=400'], (SELECT id FROM stories WHERE slug='rainmaking-traditions'), false)
