-- ============================================================
-- EDUCATIONAL_RESOURCES
-- ============================================================
INSERT INTO educational_resources (title, slug, description, subject, grade, topic, curriculum_objective, learning_outcomes, difficulty, language, estimated_duration, resource_type, content, story_id, image_url, featured) VALUES
('Great Zimbabwe: The Stone City', 'great-zimbabwe-lesson', 'Discover the history and significance of Great Zimbabwe, one of Africa''s greatest medieval civilizations.', 'Heritage Studies', 'Grade 6', 'Great Zimbabwe', 'Understand the historical and cultural significance of Great Zimbabwe as a centre of trade, architecture, and political power.', 'By the end of this lesson, learners will be able to:\n1. Describe the location and structure of Great Zimbabwe\n2. Explain the economic activities of the Kingdom of Zimbabwe\n3. Identify the cultural significance of the Zimbabwe Bird\n4. Discuss why Great Zimbabwe is important to national identity', 'intermediate', 'English', '45 minutes', 'lesson', '## Introduction\nGreat Zimbabwe is one of the most important archaeological sites in Africa. Built between the 11th and 15th centuries, it was the capital of the Kingdom of Zimbabwe — a powerful trading empire.\n\n## The Architecture\nThe city was built using dry-stone construction — granite blocks fitted together without mortar. The walls, some up to 11 metres high, demonstrate remarkable engineering skill.\n\nKey areas:\n- **Hill Complex** — the oldest section, believed to be the royal residence\n- **Great Enclosure** — the largest single ancient structure in sub-Saharan Africa\n- **Valley Ruins** — residential areas\n\n## Trade and Economy\nGreat Zimbabwe was a trading centre. Gold, ivory, and copper were traded for goods from as far as China. Archaeologists have found Chinese porcelain and glass beads at the site.\n\n## The Zimbabwe Bird\nSoapstone bird sculptures were found at Great Zimbabwe. These birds became the national symbol of modern Zimbabwe, representing the connection between the ancient civilisation and the modern nation.\n\n## Why It Matters\nGreat Zimbabwe proves that African civilisations built complex, prosperous societies long before European contact. The name "Zimbabwe" comes from the Shona phrase "dzimba dza mabwe" meaning "houses of stone."\n\n## Discussion Questions\n1. Why do you think the builders used stone instead of other materials?\n2. What does the trade with China tell us about Great Zimbabwe''s connections?\n3. Why is it important that the modern country is named after this ancient city?', (SELECT id FROM stories WHERE slug='great-zimbabwe-story'), 'https://images.pexels.com/photos/131736/pexels-photo-131736.jpeg?auto=compress&cs=tinysrgb&w=800', true),

('Traditional Farming Methods', 'traditional-farming-lesson', 'Learn about the indigenous farming practices that sustained Zimbabwean communities for centuries.', 'Agriculture', 'Grade 5', 'Traditional Agriculture', 'Understand traditional farming practices and their relevance to sustainable agriculture today.', 'By the end of this lesson, learners will be able to:\n1. Describe at least three traditional farming practices\n2. Explain how intercropping works and its benefits\n3. Discuss the role of rainmaking ceremonies in the agricultural calendar\n4. Compare traditional and modern farming methods', 'beginner', 'English', '40 minutes', 'lesson', '## Introduction\nLong before modern farming, Zimbabwean communities developed sophisticated agricultural systems that worked with nature rather than against it.\n\n## Intercropping\nInstead of planting one crop per field, traditional farmers planted multiple crops together — maize, sorghum, millet, and groundnuts. This method:\n- Maximises use of space\n- Reduces pest damage (pests prefer single-crop fields)\n- Improves soil nutrition (legumes add nitrogen)\n- Provides insurance if one crop fails\n\n## Crop Rotation\nFields were rotated and rested to preserve soil fertility. A field might be used for two seasons, then left fallow to recover.\n\n## Seed Saving\nCommunities maintained diverse seed varieties, selected for taste, drought resistance, and storage quality. Seeds were stored in special containers with ash or plant extracts to protect against insects.\n\n## The Agricultural Calendar\nPlanting was guided by natural signs:\n- Flowering of certain trees indicated rain was coming\n- Bird movements signalled seasonal changes\n- Moon phases guided planting times\n\n## Rainmaking Ceremonies\nThe Mukwerera ceremony asked ancestors and Mwari for good rains. These ceremonies also synchronised planting times across communities.\n\n## Why This Matters Today\nClimate change is making rainfall unpredictable. Many traditional practices — like intercropping and seed diversity — are now recognised as climate-smart agriculture.\n\n## Activity\nInterview an elder in your community about farming practices they remember from their childhood. What has changed? What has stayed the same?', (SELECT id FROM stories WHERE slug='traditional-farming'), 'https://images.pexels.com/photos/2933243/pexels-photo-2933243.jpeg?auto=compress&cs=tinysrgb&w=800', true),

('Rivers and Landscapes of Zimbabwe', 'rivers-landscapes-lesson', 'Explore Zimbabwe''s major rivers, mountains, and natural landmarks and their cultural significance.', 'Geography', 'Grade 7', 'Physical Geography', 'Identify major geographical features of Zimbabwe and understand their cultural and economic importance.', 'By the end of this lesson, learners will be able to:\n1. Name and locate Zimbabwe''s major rivers\n2. Describe the Eastern Highlands and their characteristics\n3. Explain the cultural significance of Victoria Falls\n4. Discuss how geography shapes human activity', 'intermediate', 'English', '50 minutes', 'lesson', '## Zimbabwe''s Geography\nZimbabwe is a landlocked country in southern Africa with diverse landscapes — from high mountains to river valleys to savanna plains.\n\n## Major Rivers\n- **Zambezi River** — forms the northern border, home to Victoria Falls and Lake Kariba\n- **Limpopo River** — forms the southern border\n- **Save River** — flows through the eastern lowveld\n- **Manyame River** — flows through the central plateau\n\nRivers are not just geographical features — they are cultural ones. The Zambezi is home to the Tonga people and the spirit Nyaminyami. Rivers provide water, food, transportation, and spiritual connection.\n\n## The Eastern Highlands\nThe Eastern Highlands run along the Zimbabwe-Mozambique border. Key areas:\n- **Nyanga** — mountains, ancient terraced fields, and stone ruins\n- **Bvumba** — mist forests with unique plants and animals\n- **Chimanimani** — quartz peaks popular for hiking\n\nThe highlands receive the highest rainfall in Zimbabwe and are important for agriculture and biodiversity.\n\n## Victoria Falls\nKnown locally as Mosi-oa-Tunya ("The Smoke That Thunders"), Victoria Falls is one of the world''s largest waterfalls. It is sacred to local communities and a UNESCO World Heritage Site.\n\n## Discussion\n1. How do rivers shape where people live?\n2. Why might mountains be important for cultural practices?\n3. How does Zimbabwe''s geography affect its economy?', (SELECT id FROM stories WHERE slug='victoria-falls-story'), 'https://images.pexels.com/photos/14938680/pexels-photo-14938680.jpeg?auto=compress&cs=tinysrgb&w=800', false),

('The Mbira and Zimbabwean Music', 'mbira-music-lesson', 'Discover the mbira, one of Zimbabwe''s most important traditional instruments, and its role in Shona culture.', 'Music', 'Grade 6', 'Traditional Instruments', 'Understand the cultural significance of the mbira and its role in Shona spiritual and musical traditions.', 'By the end of this lesson, learners will be able to:\n1. Describe what a mbira is and how it produces sound\n2. Explain the role of mbira in the Bira ceremony\n3. Identify how mbira music has evolved in modern times\n4. Recognise the mbira''s importance to Zimbabwean identity', 'beginner', 'English', '35 minutes', 'lesson', '## What is a Mbira?\nThe mbira dzavadzimu is a traditional Shona instrument with 22-28 metal keys mounted on a hardwood board. It is played with both thumbs and the right index finger.\n\nThe mbira is usually placed inside a large calabash gourd (deze) that amplifies the sound. Bottle caps or shells are often attached to create a buzzing sound that is considered beautiful in Shona aesthetics.\n\n## The Bira Ceremony\nThe most important context for mbira music is the Bira — an all-night ceremony where mbira is played to call ancestors. The music creates a bridge between the living and the spirit world.\n\nDuring a Bira:\n- Musicians play from sunset to sunrise\n- A spirit medium (svikiro) may become possessed by an ancestor\n- The community seeks guidance, healing, or rain\n- The music creates a communal, meditative atmosphere\n\n## Modern Evolution\nArtists like Thomas Mapfumo adapted mbira patterns to electric guitar, creating chimurenga music. Today, young musicians are mixing mbira with jazz, electronic, and hip-hop.\n\n## Activity\nListen to a recording of mbira music. What do you hear? How does it make you feel? Try to identify the repeating patterns.', (SELECT id FROM stories WHERE slug='mbira-music'), 'https://images.pexels.com/photos/167636/pexels-photo-167636.jpeg?auto=compress&cs=tinysrgb&w=800', true),

('Resistance and Independence', 'resistance-independence-lesson', 'Learn about the spirit mediums and leaders who resisted colonisation and the path to independence.', 'History', 'Grade 7', 'Colonial Period and Independence', 'Understand the role of spirit mediums in resistance and the path to Zimbabwe''s independence.', 'By the end of this lesson, learners will be able to:\n1. Describe the role of Mbuya Nehanda in the First Chimurenga\n2. Explain the connection between spiritual authority and political resistance\n3. Outline key events leading to independence in 1980\n4. Discuss the meaning of "Chimurenga"', 'intermediate', 'English', '45 minutes', 'lesson', '## The First Chimurenga (1896-1897)\nWhen British colonisers arrived in the 1890s, they faced resistance from both Shona and Ndebele people. The uprising of 1896-97 became known as the First Chimurenga.\n\n## Mbuya Nehanda\nMbuya Nehanda Charwe Nyakasikana was a Shona spirit medium whose authority came from the spirit (mhondoro) that possessed her. She rallied communities to resist forced labour, land seizure, and taxation.\n\nHer famous words before her execution — "Mapfupa angu achamuka" ("My bones will rise") — became a prophecy that inspired the independence struggle decades later.\n\n## The Second Chimurenga\nThe armed struggle for independence in the 1960s and 1970s was called the Second Chimurenga, directly connecting to the earlier resistance. Spirit mediums played roles in this struggle as well, providing spiritual legitimacy to the fighters.\n\n## Independence\nZimbabwe gained independence on 18 April 1980. The legacy of resistance — from Mbuya Nehanda to the guerrilla fighters — is central to the nation''s founding story.\n\n## Discussion\n1. Why were spirit mediums able to unite communities for resistance?\n2. What does "Chimurenga" mean and why was it used for both struggles?\n3. How does historical memory shape national identity?', (SELECT id FROM stories WHERE slug='womens-heritage'), 'https://images.pexels.com/photos/3752854/pexels-photo-3752854.jpeg?auto=compress&cs=tinysrgb&w=800', false),

('Great Zimbabwe Revision Notes', 'great-zimbabwe-revision', 'Quick revision notes covering the key facts about Great Zimbabwe for exam preparation.', 'Heritage Studies', 'Grade 6', 'Great Zimbabwe', 'Consolidate knowledge about Great Zimbabwe for assessment.', 'Quick reference revision sheet with key facts, dates, and terms.', 'intermediate', 'English', '15 minutes', 'revision_notes', '## Key Facts\n- **Location**: Near Masvingo, southeastern Zimbabwe\n- **Period**: Built 11th–15th century CE\n- **Peak population**: Up to 18,000 people\n- **UNESCO World Heritage Site**: Designated 1986\n- **Name origin**: "Dzimba dza mabwe" = "houses of stone" in Shona\n\n## Three Main Areas\n1. **Hill Complex** — oldest section, royal residence\n2. **Great Enclosure** — largest ancient structure in sub-Saharan Africa\n3. **Valley Ruins** — residential quarters\n\n## Construction\n- Dry-stone walls (no mortar)\n- Granite blocks split from surrounding hills\n- Walls up to 11 metres high, some 5 metres thick\n\n## Trade\n- **Exports**: Gold, ivory, copper\n- **Imports**: Chinese porcelain, glass beads, cotton cloth\n- **Trade networks**: Reached as far as China, India, and the Middle East\n\n## The Zimbabwe Bird\n- Carved from soapstone\n- Found at the site\n- National symbol of modern Zimbabwe\n- Appears on the national flag and currency\n\n## Decline\n- Abandoned around 1450 CE\n- Possible causes: environmental pressure, trade route shifts, political instability\n\n## Key Terms\n- **Dzimba dza mabwe** — houses of stone\n- **Mwari** — supreme deity in Shona religion\n- **Dry-stone construction** — building without mortar\n- **Soapstone** — soft stone used for carving', (SELECT id FROM stories WHERE slug='great-zimbabwe-story'), 'https://images.pexels.com/photos/131736/pexels-photo-131736.jpeg?auto=compress&cs=tinysrgb&w=800', false)
ON CONFLICT (slug) DO NOTHING;

