-- Great Zimbabwe Quiz
INSERT INTO quiz_questions (quiz_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
((SELECT id FROM quizzes WHERE slug='great-zimbabwe-quiz'), 'What does the name "Zimbabwe" mean in Shona?', 'Houses of stone', 'Great mountain', 'River of gold', 'Land of elephants', 'A', '"Dzimba dza mabwe" means "houses of stone," referring to the Great Zimbabwe ruins.', 1),
((SELECT id FROM quizzes WHERE slug='great-zimbabwe-quiz'), 'During which centuries was Great Zimbabwe built?', '5th–9th century', '11th–15th century', '16th–18th century', '1st–4th century', 'B', 'Great Zimbabwe was built between the 11th and 15th centuries CE.', 2),
((SELECT id FROM quizzes WHERE slug='great-zimbabwe-quiz'), 'What construction method was used at Great Zimbabwe?', 'Mud brick', 'Cement and stone', 'Dry-stone (no mortar)', 'Wood and clay', 'C', 'The walls were built using dry-stone construction — granite blocks fitted without mortar.', 3),
((SELECT id FROM quizzes WHERE slug='great-zimbabwe-quiz'), 'Which of these items was found at Great Zimbabwe, showing trade with Asia?', 'Roman coins', 'Chinese porcelain', 'Indian swords', 'Japanese pottery', 'B', 'Chinese porcelain fragments and glass beads were found, proving trade with Asia.', 4),
((SELECT id FROM quizzes WHERE slug='great-zimbabwe-quiz'), 'What is the Zimbabwe Bird carved from?', 'Granite', 'Wood', 'Soapstone', 'Ivory', 'C', 'The Zimbabwe Bird sculptures were carved from soapstone.', 5),
((SELECT id FROM quizzes WHERE slug='great-zimbabwe-quiz'), 'Approximately how many people may have lived at Great Zimbabwe at its peak?', '1,000', '5,000', '18,000', '100,000', 'C', 'At its peak, Great Zimbabwe may have housed up to 18,000 people.', 6)
ON CONFLICT DO NOTHING;

