((SELECT id FROM quizzes WHERE slug='traditional-farming-quiz'), 'What is the Mukwerera ceremony?', 'A harvest festival', 'A rainmaking ceremony', 'A marriage ceremony', 'A funeral rite', 'B', 'The Mukwerera is a traditional Shona rainmaking ceremony asking ancestors and Mwari for good rains.', 2),
((SELECT id FROM quizzes WHERE slug='traditional-farming-quiz'), 'Why did traditional farmers save seeds?', 'To sell them at market', 'To maintain diverse varieties adapted to local conditions', 'Because they had no other choice', 'To offer them to spirits', 'B', 'Seed saving maintained diverse varieties adapted to local conditions, selected for taste, drought resistance, and storage.', 3),
((SELECT id FROM quizzes WHERE slug='traditional-farming-quiz'), 'What natural signs guided planting times?', 'Radio broadcasts', 'Newspaper weather reports', 'Tree flowering and bird movements', 'Government announcements', 'C', 'Traditional farmers observed tree flowering, bird movements, and moon phases to guide planting.', 4),
((SELECT id FROM quizzes WHERE slug='traditional-farming-quiz'), 'Why are traditional farming practices relevant today?', 'They are not relevant anymore', 'They offer climate-resilient, sustainable approaches', 'They produce more food than modern farming', 'They are required by law', 'B', 'Many traditional practices like intercropping and seed diversity are now recognised as climate-smart agriculture.', 5)
ON CONFLICT DO NOTHING;

