INSERT INTO submissions (title, content_type, description, contributor_name, contributor_email, community, language, province, place_name, status, image_url, consent_given, admin_notes) VALUES
('Story of the Baobab Tree at Chiredzi', 'story', 'My grandmother told me about a sacred baobab tree near our village in Chiredzi that was used as a meeting place for elders. The tree is estimated to be over 500 years old. I want to document this story for future generations.', 'Farai Mudzingwa', 'farai.m@example.com', 'Shangaan', 'Shangaan', 'Masvingo', 'Chiredzi', 'community_review', 'https://images.pexels.com/photos/1031641/pexels-photo-1031641.jpeg?auto=compress&cs=tinysrgb&w=400', true, 'AI transcription completed. Researcher reviewed and confirmed plausibility. Community review in progress.'),
('Traditional Pottery Techniques of Bikita', 'oral_history', 'An interview with Gogo Muringi about how pottery was made in Bikita district using clay from the riverbed, shaped by hand, and fired in open kilns. The interview is 25 minutes long and in chiShona.', 'Patience Nziramasanga', 'patience.n@example.com', 'Shona', 'chiShona', 'Masvingo', 'Bikita', 'ai_processed', NULL, true, 'AI processing complete — transcript and summary generated. Awaiting researcher review.')
ON CONFLICT DO NOTHING;

